        ros: 'Positive for wheeze, chest tightness, dyspnea, dry cough, and fatigue with nasal congestion/sore throat earlier in the week. Negative for fever above 101 F, productive purulent sputum, chest pain, hemoptysis, leg swelling, orthopnea and recent medication changes.',
        keyLabs: ['pH', 'PaCO2', 'PaO2', 'Potassium', 'Glucose', 'WBC', 'Lactate'], hpLabs: ['WBC', 'Sodium', 'Potassium', 'Creatinine', 'Glucose', 'Lactate', 'pH', 'PaCO2', 'PaO2', 'BNP'],
